WITH unpacked AS (SELECT id, service, log_ts, payload_json, context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, COALESCE(context['trace'], 'unknown') AS trace_or_default, COALESCE(context['version'], 'unknown') AS version_or_default, SIZE(context) AS num_context FROM app_logs) SELECT id, service, log_ts, payload_json, context, duration_text, trace_or_default, version_or_default, num_context, ROW_NUMBER() OVER (PARTITION BY service ORDER BY num_context DESC, id) AS event_seq, LAST_VALUE(num_context, TRUE) OVER (PARTITION BY service ORDER BY num_context, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_num_context FROM unpacked;
